class Solution:
    def limitOccurrences(self, nums: List[int], k: int) -> List[int]:
        res = []
        i, n = 0, len(nums)
        while i < n:
            j = i
            while j < n and nums[j] == nums[i]:
                j += 1
            res.extend([nums[i]] * min(j - i, k))
            i = j
        return res

