class Solution {
public:
    vector<int> limitOccurrences(vector<int>& nums, int k) {
        vector<int> res;
        int i = 0, n = nums.size();
        while (i < n) {
            int j = i;
            while (j < n && nums[j] == nums[i]) j++;
            for (int t = 0; t < min(j - i, k); t++) res.push_back(nums[i]);
            i = j;
        }
        return res;
    }
};

