class Solution:
    def limitOccurrences(self, nums: List[int], k: int) -> List[int]:
        write = 0
        count = 0
        for x in nums:
            if write > 0 and nums[write - 1] == x:
                count += 1
            else:
                count = 1
            if count <= k:
                nums[write] = x
                write += 1
        return nums[:write]

